import XCTest
import MoqTestSupport

/// Generated by amoo from the Studio test "DeleteAllMocked". Edit freely — this file has no
/// dependency on amoo or the companion apps once generated.
@MainActor
final class DeleteAllMockedTest: XCTestCase {
    private let defaultTimeout: TimeInterval = 5
    private var moqSession: MoqClient?
    /// The moqserver session setUp opened for this test.
    private func moq() throws -> MoqClient {
        try XCTUnwrap(moqSession, "No moqserver session: setUp did not finish")
    }
    private lazy var app = XCUIApplication()

    override func setUp() async throws {
        try await super.setUp()
        continueAfterFailure = false
        let moqPort = ProcessInfo.processInfo.environment["MOQ_PORT"] ?? "8080"
        let moqAdminURL = try XCTUnwrap(URL(string: "http://127.0.0.1:\(moqPort)"))
        let moqClient = try MoqClient(baseURL: moqAdminURL).createSession()
        moqSession = moqClient
        let moqSessionID = try XCTUnwrap(moqClient.sessionID)
        let moqBaseURL = "http://127.0.0.1:\(moqPort)"
        app.launchEnvironment["APP_AUTH_EMULATOR_HOST"] = "127.0.0.1:9099"
        app.launchEnvironment["APP_MOCK_BASE_URL"] = "\(moqBaseURL)"
        app.launchEnvironment["APP_MOCK_SESSION"] = "\(moqSessionID)"
        app.launch()
    }

    override func tearDown() async throws {
        if testRun?.failureCount ?? 0 > 0 {
            let screenshot = XCTAttachment(screenshot: app.screenshot())
            screenshot.name = "Failure screenshot"
            screenshot.lifetime = .keepAlways
            add(screenshot)

            let hierarchy = XCTAttachment(string: app.debugDescription)
            hierarchy.name = "Failure UI hierarchy"
            hierarchy.lifetime = .keepAlways
            add(hierarchy)
        }
        try moqSession?.closeSession()
        try await super.tearDown()
    }

    private func waitForExistence(
        _ element: XCUIElement,
        named name: String = "Element",
        timeout: TimeInterval? = nil,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertTrue(
            element.waitForExistence(timeout: timeout ?? defaultTimeout),
            "\(name) did not exist before the timeout.\n\(element.debugDescription)",
            file: file,
            line: line
        )
    }

    private func waitForHittability(
        _ element: XCUIElement,
        named name: String = "Element",
        timeout: TimeInterval? = nil,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertTrue(
            element.wait(for: \.isHittable, toEqual: true, timeout: timeout ?? defaultTimeout),
            "\(name) was not visible and hittable before the timeout.\n\(element.debugDescription)",
            file: file,
            line: line
        )
    }

    private func waitForAbsence(
        _ element: XCUIElement,
        named name: String = "Element",
        timeout: TimeInterval? = nil,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertTrue(
            element.wait(for: \.exists, toEqual: false, timeout: timeout ?? defaultTimeout),
            "\(name) still existed after the timeout.\n\(element.debugDescription)",
            file: file,
            line: line
        )
    }

    private func replaceText(in element: XCUIElement, with text: String) {
        element.tap()
        if let currentValue = element.value as? String, !currentValue.isEmpty {
            element.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: currentValue.count))
        }
        if !text.isEmpty {
            element.typeText(text)
        }
    }

    private func pressBack() {
        let backButton = app.navigationBars.buttons.element(boundBy: 0)
        if backButton.exists, backButton.isHittable {
            backButton.tap()
        } else {
            app.swipeRight()
        }
    }

    func testDeleteAllMocked() throws {
        let email = app.descendants(matching: .any)["signIn.email"]
        waitForHittability(email, named: "email", timeout: 10.0)
        replaceText(in: email, with: "user@example.com")
        let password = app.descendants(matching: .any)["signIn.password"]
        waitForHittability(password, named: "password", timeout: 5.0)
        replaceText(in: password, with: "example-password")
        let submit = app.descendants(matching: .any)["signIn.submit"]
        waitForHittability(submit, named: "submit", timeout: 5.0)
        submit.tap()
        let count = app.descendants(matching: .any)["tasks.count"]
        waitForHittability(count, named: "count", timeout: 10.0)
        let count2 = app.descendants(matching: .any).matching(identifier: "tasks.count").matching(NSPredicate(format: "label CONTAINS %@", "3 tasks")).firstMatch
        waitForHittability(count2, named: "count2", timeout: 5.0)
        _ = try moq().assertRequest(timeout: 5)
        let edit = app.descendants(matching: .any)["tasks.edit"]
        waitForHittability(edit, named: "edit", timeout: 5.0)
        edit.tap()
        let deleteAll = app.descendants(matching: .any)["tasks.deleteAll"]
        waitForHittability(deleteAll, named: "deleteAll", timeout: 5.0)
        try moq().selectVariant("empty", for: "GET", path: "/v1/tasks")
        let moqMarkBeforeDeleteAll = try moq().mark()
        waitForHittability(deleteAll, named: "deleteAll", timeout: 5.0)
        deleteAll.tap()
        let thisCantBeUndone = app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS %@", "This can't be undone.")).firstMatch
        waitForHittability(thisCantBeUndone, named: "thisCantBeUndone", timeout: 5.0)
        let confirm = app.descendants(matching: .any).matching(identifier: "tasks.deleteAll.confirm").firstMatch
        waitForHittability(confirm, named: "confirm", timeout: 5.0)
        confirm.tap()
        let empty = app.descendants(matching: .any)["tasks.empty"]
        waitForHittability(empty, named: "empty", timeout: 10.0)
        _ = try moq().assertRequest(endpoint: "DELETE /v1/tasks", times: 1, since: moqMarkBeforeDeleteAll, timeout: 3)
        try moq().assertNoRejectedRequests()
        try moq().assertNoUnmatchedRequests()
        _ = try moq().assertAllRequestsCarrySession()
    }
}
